DROP VIEW IF EXISTS `v_assessment_performance`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_assessment_performance` AS select `u`.`UserID` AS `UserID`,`u`.`Name` AS `Name`,`a`.`AssessmentID` AS `AssessmentID`,`a`.`AssessmentType` AS `AssessmentType`,`a`.`DateTaken` AS `DateTaken`,`a`.`TotalScore` AS `TotalScore`,`a`.`ResultStatus` AS `ResultStatus`,count(`ua`.`AnswerID`) AS `total_questions`,sum((case when (`ua`.`IsCorrect` = true) then 1 else 0 end)) AS `correct_answers` from ((`user` `u` left join `assessment` `a` on((`u`.`UserID` = `a`.`UserID`))) left join `user_answer` `ua` on((`a`.`AssessmentID` = `ua`.`AssessmentID`))) group by `u`.`UserID`,`a`.`AssessmentID`;

DROP VIEW IF EXISTS `v_bkt_knowledge_state`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_bkt_knowledge_state` AS select `u`.`UserID` AS `UserID`,`u`.`Name` AS `Name`,`bkt`.`SkillName` AS `SkillName`,`bkt`.`PKnown` AS `PKnown`,`bkt`.`CurrentL` AS `CurrentL`,`bkt`.`PLearn` AS `PLearn`,`bkt`.`PSlip` AS `PSlip`,`bkt`.`PGuess` AS `PGuess`,`om`.`WMInitial` AS `WMInitial`,`om`.`TMLesson` AS `TMLesson`,`om`.`OverallMastery` AS `OverallMastery`,`om`.`OverallMasteryPercent` AS `OverallMasteryPercent`,`om`.`IsMastered` AS `IsMastered`,(case when (`om`.`OverallMastery` >= 0.85) then 'Mastered' when (`om`.`OverallMastery` >= 0.70) then 'Advanced' when (`om`.`OverallMastery` >= 0.50) then 'Intermediate' when (`om`.`OverallMastery` >= 0.30) then 'Beginner' else 'Novice' end) AS `proficiency_level` from ((`user` `u` left join `bkt_model` `bkt` on((`u`.`UserID` = `bkt`.`UserID`))) left join `bkt_overall_mastery` `om` on(((`u`.`UserID` = `om`.`UserID`) and (`bkt`.`SkillName` = `om`.`SkillName`))));

DROP VIEW IF EXISTS `v_learning_skill_analysis`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_learning_skill_analysis` AS select `u`.`UserID` AS `UserID`,`u`.`Name` AS `Name`,`ls`.`SkillCategory` AS `SkillCategory`,avg(`ls`.`ScorePercentage`) AS `average_score`,count(`ls`.`SkillID`) AS `evaluation_count`,max(`ls`.`EvaluationDate`) AS `last_evaluation` from (`user` `u` left join `learning_skill` `ls` on((`u`.`UserID` = `ls`.`UserID`))) group by `u`.`UserID`,`ls`.`SkillCategory`;

DROP VIEW IF EXISTS `v_lesson_mastery_summary`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_lesson_mastery_summary` AS select `u`.`UserID` AS `UserID`,`u`.`Name` AS `Name`,`m`.`ModuleID` AS `ModuleID`,`m`.`ModuleTitle` AS `ModuleTitle`,`m`.`LessonOrder` AS `LessonOrder`,`lm`.`SkillName` AS `SkillName`,`lm`.`ReviewL` AS `ReviewL`,`lm`.`SimulationL` AS `SimulationL`,`lm`.`FinalL` AS `FinalL`,`lm`.`MLesson` AS `MLesson`,`lm`.`WMLesson` AS `WMLesson`,`lm`.`IsPassed` AS `IsPassed`,`lm`.`RetakeCount` AS `RetakeCount` from ((`user` `u` join `bkt_lesson_mastery` `lm` on((`u`.`UserID` = `lm`.`UserID`))) join `module` `m` on((`lm`.`ModuleID` = `m`.`ModuleID`))) order by `u`.`UserID`,`m`.`LessonOrder`,`lm`.`SkillName`;

DROP VIEW IF EXISTS `v_user_progress_summary`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_user_progress_summary` AS select `u`.`UserID` AS `UserID`,`u`.`Name` AS `Name`,`u`.`Email` AS `Email`,`m`.`ModuleID` AS `ModuleID`,`m`.`ModuleTitle` AS `ModuleTitle`,`p`.`CompletionRate` AS `CompletionRate`,`p`.`DateStarted` AS `DateStarted`,`p`.`DateCompletion` AS `DateCompletion` from ((`user` `u` left join `progress` `p` on((`u`.`UserID` = `p`.`UserID`))) left join `module` `m` on((`p`.`ModuleID` = `m`.`ModuleID`)));













SET FOREIGN_KEY_CHECKS=1;
