(14, 'Disassembling the HDD', 'Navigate the system unit case to familiarize yourself with the motherboard.', 'Adaptive Workflow', 100, 0, 5, '2026-04-10 08:41:43', '2026-04-17 06:07:35', '{\"instructionText\":\"1. Unplug the power cable from the system unit.\\n2. Open the system unit case.\\n3. Go to the HDD bay area.\\n4. Unplug the SATA data and power cables from the HDD.\\n5. Pull the HDD out from the drive bay and set aside.\",\"skillType\":\"Critical Thinking\",\"flowSteps\":[{\"id\":1,\"text\":\"Unplug the power cable from the system unit.\",\"actionType\":\"interact\",\"perspectiveId\":1,\"targetLabel\":\"Step 2: Shade Base\",\"requiredTool\":\"hand\"},{\"id\":2,\"text\":\"Open the system unit case.\",\"actionType\":\"mark\",\"perspectiveId\":1,\"targetLabel\":\"Step 3: Cover\",\"requiredTool\":\"hand\"},{\"id\":3,\"text\":\"Go to the HDD bay area.\",\"actionType\":\"mark\",\"perspectiveId\":1,\"targetLabel\":\"Step 4: Base\",\"requiredTool\":\"hand\"},{\"id\":4,\"text\":\"Unplug the SATA data and power cables from the HDD.\",\"actionType\":\"interact\",\"perspectiveId\":1,\"targetLabel\":\"Step 5: Connectors HDD Area\",\"requiredTool\":\"hand\"},{\"id\":5,\"text\":\"Pull the HDD out from the drive bay and set aside.\",\"actionType\":\"drag\",\"perspectiveId\":1,\"targetLabel\":\"Step 6: HDD Area\",\"requiredTool\":\"hand\"}],\"mainAreas\":[{\"id\":1,\"name\":\"Computer Case - External View\",\"backgroundImage\":\"/uploads/simulations/Activity 5/1. Plug - Back.webp\",\"dropZones\":[{\"id\":1,\"x\":16,\"y\":16,\"label\":\"Step 2: Shade Base\",\"smallImage\":\"/uploads/simulations/Activity 5/2. Shade - Base.webp\",\"layerImage\":\"/uploads/simulations/Activity 5/2. Shade - Base.webp\",\"layerOrder\":2,\"interactionMode\":\"drag\",\"requiredTool\":\"hand\"},{\"id\":2,\"x\":34,\"y\":16,\"label\":\"Step 3: Cover\",\"smallImage\":\"/uploads/simulations/Activity 5/3. Cover.webp\",\"layerImage\":\"/uploads/simulations/Activity 5/3. Cover.webp\",\"layerOrder\":3,\"interactionMode\":\"drag\",\"requiredTool\":\"hand\"},{\"id\":3,\"x\":52,\"y\":16,\"label\":\"Step 4: Base\",\"smallImage\":\"/uploads/simulations/Activity 5/4. Base.webp\",\"layerImage\":\"/uploads/simulations/Activity 5/4. Base.webp\",\"layerOrder\":4,\"interactionMode\":\"drag\",\"requiredTool\":\"hand\"},{\"id\":4,\"x\":70,\"y\":16,\"label\":\"Step 5: Connectors HDD Area\",\"smallImage\":\"/uploads/simulations/Activity 5/5. Connectors - HDD Area.webp\",\"layerImage\":\"/uploads/simulations/Activity 5/5. Connectors - HDD Area.webp\",\"layerOrder\":5,\"interactionMode\":\"click\",\"requiredTool\":\"hand\"},{\"id\":5,\"x\":88,\"y\":16,\"label\":\"Step 6: HDD Area\",\"smallImage\":\"/uploads/simulations/Activity 5/6. HDD - Area.webp\",\"layerImage\":\"/uploads/simulations/Activity 5/6. HDD - Area.webp\",\"layerOrder\":6,\"interactionMode\":\"drag\",\"requiredTool\":\"hand\"},{\"id\":6,\"x\":16,\"y\":35,\"label\":\"Step 7: Base HDD Area\",\"smallImage\":\"/uploads/simulations/Activity 5/7. Base - HDD Area.webp\",\"layerImage\":\"/uploads/simulations/Activity 5/7. Base - HDD Area.webp\",\"layerOrder\":7,\"interactionMode\":\"drag\",\"requiredTool\":\"hand\"}]}],\"backgroundImage\":\"/uploads/simulations/Activity 5/1. Plug - Back.webp\",\"dropZones\":[{\"id\":1,\"x\":16,\"y\":16,\"label\":\"Step 2: Shade Base\",\"smallImage\":\"/uploads/simulations/Activity 5/2. Shade - Base.webp\",\"layerImage\":\"/uploads/simulations/Activity 5/2. Shade - Base.webp\",\"layerOrder\":2,\"interactionMode\":\"drag\",\"requiredTool\":\"hand\"},{\"id\":2,\"x\":34,\"y\":16,\"label\":\"Step 3: Cover\",\"smallImage\":\"/uploads/simulations/Activity 5/3. Cover.webp\",\"layerImage\":\"/uploads/simulations/Activity 5/3. Cover.webp\",\"layerOrder\":3,\"interactionMode\":\"drag\",\"requiredTool\":\"hand\"},{\"id\":3,\"x\":52,\"y\":16,\"label\":\"Step 4: Base\",\"smallImage\":\"/uploads/simulations/Activity 5/4. Base.webp\",\"layerImage\":\"/uploads/simulations/Activity 5/4. Base.webp\",\"layerOrder\"